\label{thm: equation}
{Let $G$ be a finite abelian group of order $n$} and let $K$ be a field in which $n$ is invertible.
The TPE system consist of $d_\varrho,c\in K^\times$, a
nondegenerate symmetric bicharacter $\chi:G\times G\to K^\times$,
$a:G\to K^\times$, and $\beta:G\to K$, satisfying
\begin{align}
 d_\varrho^2&=n+nd_\varrho,\label{eq:dim_rho}\\
 a(-g)&=a(g),\qquad a(0)=1,\label{eq:apm}\\
 a(g+h)\chi(g,h)&=a(g)a(h),\label{eq:achi}\\
 c^3\sum_{g\in G}a(g)&=\frac1n,\label{eq:c_nonzero}\\
 \sum_{g\in G}a(g)^{-1}\chi(h,g)\beta(g)&=cn\beta(h),\label{eq:Fourier}\\
 \beta(g)\beta(-g)+\frac{\delta_{g,0}}{d_\varrho}&=\frac{a(g)}n,\label{eq:betapm}\\
 \frac{a(h-g)}n\sum_{k\in G}\chi(h,k)^{-1}
 \frac{\beta(g-k)\beta(k)}{a(k)}
 &=\beta(-h)\beta(g)\beta(h-g)+\frac{\delta_{h,0}\delta_{g,0}}{d_\varrho}.
 \label{eq:two_beta_identity}
\end{align}
A unitary TPE system over $ K = \mathbb{C} $ requires further
\begin{align}
  d &> 0, \\
  \overline{\beta(g)} &= \frac{\beta(-g)}{a(g)}.
\end{align}

Two main reasons motivate our focus on trivial Frobenius--Schur indicators:
    \begin{enumerate}
        \item Rather than providing a complete classification of near-group fusion categories, our primary goal is to construct an infinite family of $2^G 1$ subfactors for $G = C_p$, a cyclic group of odd prime order. In this setting, the Frobenius--Schur indicator of any self-dual simple object $X \cong X^*$ is always $1$.
        \item Over fields of characteristic two, the Frobenius--Schur indicator is automatically trivial.
    \end{enumerate}

\label{lem:BSS_identity}
  Let $ \alpha, g\in \mathbb{C} $ such that $ 0 < \mathrm{Re}(\alpha) < \mathrm{Re}(\Omega + g) $
  \begin{align}
&\int_{-i\infty}^{i\infty}e^{\pi i z(2\alpha-g-\Omega)/n}
 \gamma(z-g)\gamma(-z)\frac{dz}{i\sqrt n}\nonumber
&\qquad=e^{\pi i g(2\alpha-g-\Omega)/(2n)}
 \gamma(\alpha)\gamma(\Omega+g-\alpha)\gamma(-g),
 \tag{BSS}\label{eq:BSS}
\end{align}

\label{lem:S-residue-continuation}
For \(1\le g<n\) and \(0\le h<n\), define
\[
S_{g,h}
:=
\sum_{k=0}^{n-1}
(-1)^k
\exp\left(\frac{\pi i(g-2h)k}{n}\right)
F(k)F(g-k).
\]
Then
\begin{equation}\label{eq:finite-sum-F-final}
S_{g,h}
=
\sqrt{n}\,F(g)
\frac{s(\overline{-h})}{s(\overline{g-h})}
F(\overline{-h})F(\overline{h-g}).
\end{equation}

Let $\chi, a$ and $ s $ be defined as in \eqref{eq:explicit-quadratic-data} and \eqref{eq:s-definition}, and Let 
    \begin{align*}
      \beta(k) = \frac{s(k)F(k)}{\sqrt{n}}, \qquad 0\le k < n,
    \end{align*}
    Then $ d_{-}, \chi, a, \beta $ satisfy the TPE system.

It suffices to verify Equation~\eqref{eq:two_beta_identity} for $ g\ne 0 $.
By the definition of \(\beta\),
\[
\begin{aligned}
&\sum_{k\in G}
\overline{\chi(h,k)}
\frac{\beta(g-k)\beta(k)}{a(k)}
=
\frac1n
\sum_{k=0}^{n-1}
e^{-2\pi i hk/n}
\frac{s(\overline{g-k})}
     {s(k)}
F(\overline{g-k})F(k).
\end{aligned}
\]
Using the \(n\)-periodicity of \(s(x)F(x)\) on integer arguments,
\[
\frac{s(\overline{g-k})}{s(k)}
F(\overline{g-k})
=
s(g)(-1)^k
e^{\pi i gk/n}
F(g-k),
\]
and hence
\begin{equation}\label{eq:cubic-S-direct}
\sum_{k\in G}
\overline{\chi(h,k)}
\frac{\beta(g-k)\beta(k)}{a(k)}
=
\frac{s(g)}nS_{g,h}.
\end{equation}

Applying Lemma~\ref{lem:S-residue-continuation},
\[
\begin{aligned}
\frac{a(h-g)}n
\sum_{k\in G}
\overline{\chi(h,k)}
\frac{\beta(g-k)\beta(k)}{a(k)}&=
\frac{a(h-g)s(g)}{n^2}
S_{g,h}
\\
&=
\frac{
s(g)
s(\overline{h-g})
s(\overline{-h})
}{
n^{3/2}
}
F(g)
F(\overline{h-g})
F(\overline{-h}).
\end{aligned}
\]
Since
\[
a(h-g)=s(\overline{h-g})^2,
\]
the last expression is exactly
\[
\beta(-h)\beta(g)\beta(h-g).
\]
Thus
\[
\frac{a(h-g)}n
\sum_{k\in G}
\overline{\chi(h,k)}
\frac{\beta(g-k)\beta(k)}{a(k)}
=
\beta(-h)\beta(g)\beta(h-g),
\]
which is the desired identity for \(g\neq0\).

\label{lem:algebraic-reflection}
The rational transformation
\begin{equation}\label{eq:parameter-reflection}
 \tau(d,\chi,a,c,\beta)
 =\left(d,\chi^{-1},a^{-1},\frac1{nc},
        \left(g\longmapsto\frac{\beta(-g)}{a(g)}\right)\right)
\end{equation}
is an involution of the solution set of Definition~\ref{thm: equation},
over every field allowed there.

\label{lem:izumi-cubic-dictionary}
Assume the quadratic and Fourier equations and $\beta(0)=-1/d$.
Then~\eqref{eq:two_beta_identity} is equivalent to
\begin{equation}\label{eq:izumi-cubic-form}
 \sum_{t\in G}\frac{\beta(-t)\beta(t+u)\beta(t+v)}{a(t)}
 =\chi(u,v)\beta(u)\beta(v)-\frac1{cdn}
 \qquad(u,v\in G).
\end{equation}
Thus Izumi's parameters in \cite[Remark~9.2]{Izumi2017} are
$\langle g,h\rangle_I=\chi(g,h)^{-1}$,
$a_I(g)=a(g)^{-1}$, $c'_I=c$, and $b_I(g)=\beta(g)$.

\label{pro: normalization}
Let $a,b,c$ be simple objects with
$\operatorname{Hom}(\mathbf1,a\otimes b\otimes c)\ne0$, and suppose
that one is invertible. Choose opposite vertices
$\beta:\mathbf1\to a\otimes b\otimes c$ and
$\alpha:a\otimes b\otimes c\to\mathbf1$ with
\begin{equation}\label{equ: normalisation}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D002\endcsname}}}=\theta(a,b,c),\qquad
 \theta(a,b,c)=
 \begin{cases}
 1,&a,b,c\text{ are invertible},\\
 d,&\text{two of }a,b,c\text{ equal }\varrho.
 \end{cases}
\end{equation}
We suppress the vertex label on the resulting mixed vertex
$\ensuremath{\vcenter{\hbox{\csname ngdiagram@D003\endcsname}}}$ and its prescribed rotations. For every simple
$a$ and $g\in G$, the associated fusion and splitting maps satisfy
\begin{equation}\label{eq:mixed-splitting}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D004\endcsname}}}=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D005\endcsname}}}.
\end{equation}

\label{lem: coproduct}
For $g,h,k,g',h',k'\in G$ satisfying
$g+h=g'+h'$ and $k-h=k'-h'$, the coherent mixed vertices give
\begin{align}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D006\endcsname}}}&=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D007\endcsname}}},\label{equ: co 6g}\\
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D008\endcsname}}}&=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D009\endcsname}}}.\label{equ: co 3g}
\end{align}

\label{lem: F-symbol 6 inv}
For $g,h,k\in G$, the coefficients with six or three invertible edges are
\begin{equation}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D010\endcsname}}}=1,\qquad \ensuremath{\vcenter{\hbox{\csname ngdiagram@D011\endcsname}}}=d.
\end{equation}

\label{lem: bicha}
The mixed interchange coefficient is a {nondegenerate symmetric} bicharacter
$\chi:G\times G\to\mathbb T$, defined by
\begin{equation}\label{equ: bicha}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D015\endcsname}}}=\chi(g,h)\ensuremath{\vcenter{\hbox{\csname ngdiagram@D016\endcsname}}}.
\end{equation}
{In particular $\chi(g,h)=\chi(h,g)=\chi(-g,-h)$.}

The two mixed composites are proportional because their common
morphism space is one-dimensional. They are unitary composites in the
fixed mixed gauge, so their ratio has modulus $1$. Closing the
interchange relation gives
\begin{equation}\label{equ: def of chi}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D017\endcsname}}}=\chi(g,h)d.
\end{equation}
The prism
\begin{equation}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D018\endcsname}}}
\end{equation}
expands in its two directions as
\begin{equation}\label{eq:bicharacter-prism}
 d\,\ensuremath{\vcenter{\hbox{\csname ngdiagram@D019\endcsname}}}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D020\endcsname}}}
 =\ensuremath{\vcenter{\hbox{\csname ngdiagram@D021\endcsname}}}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D022\endcsname}}}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D023\endcsname}}}.
\end{equation}
Substitution yields
\[
 d^3\chi(g+h,-k)=d^3\chi(g,-k)\chi(h,-k).
\]
Since $d\ne0$, this proves multiplicativity in the first variable.
Interchanging the roles of the coherent left and right module actions
in this calculation proves multiplicativity in the second variable.
Equivalently, compare the two ways of moving $g$ past the product
$h+k$: right module coherence gives
$\chi(g,h+k)=\chi(g,h)\chi(g,k)$.

The nondegeneracy follows from $\chi_g$ form the regular
representation in the irrational-dimensional case; this applies
since $d=(n+\sqrt{n^2+4n})/2$ is irrational for every $n\geq1$.
The spherical property gives $ \chi(g,h) = \chi(h,g) = \chi(-h,-g) $, since
\begin{equation}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D017\endcsname}}}=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D024\endcsname}}}=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D025\endcsname}}}.
\end{equation}

\label{pro: 3 reps}
The three mixed insertions define unitary representations
$\pi_x,\pi_y,\pi_z$ of $G$ on $V$, satisfying
\begin{align}
 \pi_z(g)\pi_x(h)&=\chi(g,h)\pi_x(h)\pi_z(g),\label{equ: zx}\\
 \pi_x(g)\pi_y(h)&=\chi(g,h)\pi_y(h)\pi_x(g),\label{equ: xy}\\
 \pi_y(g)\pi_z(h)&=\chi(g,h)\pi_z(h)\pi_y(g).
 \label{equ:yz}
\end{align}

For $\alpha\in V$, define
\begin{equation}
 \pi_x(g):\ensuremath{\vcenter{\hbox{\csname ngdiagram@D026\endcsname}}}\longmapsto\ensuremath{\vcenter{\hbox{\csname ngdiagram@D027\endcsname}}}.
\end{equation}
The coherent mixed relation gives
\begin{equation}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D028\endcsname}}}=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D029\endcsname}}},
\end{equation}
and therefore
\begin{align}
 \pi_x(g)\pi_x(h)(\alpha)
 &=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D030\endcsname}}}=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D031\endcsname}}}\notag\\
 &=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D032\endcsname}}}=\pi_x(g+h)(\alpha).
\end{align}
The other two insertions are
\begin{align}
 \pi_y(g):\ensuremath{\vcenter{\hbox{\csname ngdiagram@D026\endcsname}}}&\longmapsto\ensuremath{\vcenter{\hbox{\csname ngdiagram@D033\endcsname}}},\notag\\
 \pi_z(g):\ensuremath{\vcenter{\hbox{\csname ngdiagram@D026\endcsname}}}&\longmapsto\ensuremath{\vcenter{\hbox{\csname ngdiagram@D034\endcsname}}}.
\end{align}
The same mixed cancellation proves their representation laws.
Reflecting an insertion takes its adjoint and reverses the group strand;
hence $\pi_j(g)^\dagger=\pi_j(-g)$ for $j=x,y,z$, proving unitarity.
Finally, the mixed interchange relation gives the three pictorial
commutations
\begin{align}
 \pi_z(g)\pi_x(h)(\alpha)
 &=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D035\endcsname}}}=\chi(g,h)\ensuremath{\vcenter{\hbox{\csname ngdiagram@D036\endcsname}}}\notag\\
 &=\chi(g,h)\pi_x(h)\pi_z(g)(\alpha),\notag\\[2pt]
 \pi_x(g)\pi_y(h)(\alpha)
 &=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D037\endcsname}}}=\chi(g,h)\ensuremath{\vcenter{\hbox{\csname ngdiagram@D038\endcsname}}}\notag\\
 &=\chi(g,h)\pi_y(h)\pi_x(g)(\alpha),\notag\\[2pt]
 \pi_y(g)\pi_z(h)(\alpha)
 &=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D039\endcsname}}}=\chi(-h,-g)\ensuremath{\vcenter{\hbox{\csname ngdiagram@D040\endcsname}}}\notag\\
 &=\chi(g,h)\pi_z(h)\pi_y(g)(\alpha).
\end{align}

\label{cor: rhorhorho}
Let $G$ be a finite abelian group of order $n$. There are an
orthonormal basis $(v_h)_{h\in G}$ and an even quadratic refinement
$a:G\to\mathbb T$ such that
\begin{align}\label{eq:three-actions-normal-form}
 \pi_z(g)v_h&=\chi(g,h)v_h,&
 \pi_x(g)v_h&=v_{h+g},&
 \pi_y(g)v_h&=\frac{a(h)}{a(h-g)}v_{h-g},
\end{align}
where
\begin{equation}\label{equ: def of a}
 a(0)=1,\qquad a(-g)=a(g),\qquad
 a(g+h)\chi(g,h)=a(g)a(h).
\end{equation}
We represent $v_h$ by $\ensuremath{\vcenter{\hbox{\csname ngdiagram@D041\endcsname}}}$. The associated bilinear theta pairing is
$B(v_h,v_k)=B(v_0,v_0)\delta_{h+k,0}a(h)$.

\label{cor:bilinear-dual-basis}
Normalize the common phase by $B(v_0,v_0)=1$. The basis bilinearly
dual to $(v_h)$ is
\begin{equation}\label{eq:dual-basis}
 v_h'=a(h)^{-1}v_{-h}.
\end{equation}
Its three group actions are
\begin{align*}
 \pi_z(g)v_h'&=\chi(g,-h)v_h',&
 \pi_x(g)v_h'&=\frac{a(h-g)}{a(h)}v_{h-g}',&
 \pi_y(g)v_h'&=v_{h+g}'.
\end{align*}

\label{lem: rotation}
There is a nonzero $c\in\mathbb C$ such that
\begin{equation}\label{eq:vertex-rotation}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D053\endcsname}}}
 =c a(g)\sum_{h\in G}\chi(g,h)^{-1}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D054\endcsname}}}.
\end{equation}
Moreover,
\begin{equation}\label{eq:rotation-gauss}
 c^3S_a=\frac1n,\qquad |S_a|=\sqrt n,\qquad |c|=\frac1{\sqrt n}.
\end{equation}

The two corner conventions give bases
$\{\ensuremath{\vcenter{\hbox{\csname ngdiagram@D053\endcsname}}}:g\in G\}$ and
$\{\ensuremath{\vcenter{\hbox{\csname ngdiagram@D055\endcsname}}}:g\in G\}$.  Thus
\begin{equation}\label{eq:rotate-zero-expand}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D056\endcsname}}}=\sum_{h\in G}c_h\ensuremath{\vcenter{\hbox{\csname ngdiagram@D054\endcsname}}}.
\end{equation}
Let $R$ denote this cyclic change of corner.  Transporting the group
strands to the adjacent corner gives
$R\pi_z(l)=\pi_x(l)R$ and $R\pi_x(l)=\pi_y(l)R$.
Since $\pi_z(l)v_0=v_0$, the vector $Rv_0$ is fixed by every
$\pi_x(l)$.  The latter acts by translation in the target basis,
by Corollary~\ref{cor: rhorhorho}; hence all $c_h$ are equal.
Write their common value as $c$.
Sliding a $g$-labelled invertible strand gives
\begin{align}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D053\endcsname}}}
 &=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D057\endcsname}}}
   =c\sum_{h\in G}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D058\endcsname}}},\label{eq:rotation-slide}\\
 &=c\sum_{h\in G}\frac{a(h)}{a(h-g)}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D059\endcsname}}},\notag\\
 &=c\sum_{h\in G}\frac{a(h+g)}{a(h)}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D054\endcsname}}}
   =c a(g)\sum_{h\in G}\chi(g,h)^{-1}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D054\endcsname}}}.
   \notag
\end{align}
The last equality uses $a(h+g)\chi(g,h)=a(h)a(g)$.
The scalar $c$ cannot vanish because the change of basis is invertible.

Three successive corner changes are a full cyclic rotation.  Their
pictorial expansion is
\begin{align}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D056\endcsname}}}
 &=c\sum_{g\in G}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D060\endcsname}}},\label{eq:rotation-three}\\
 &=c^2\sum_{g,h\in G}a(g)\chi(g,h)^{-1}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D061\endcsname}}},\notag\\
 &=c^3\sum_{g,h,k\in G}
     a(g)a(h)\chi(g,h)^{-1}\chi(h,k)^{-1}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D062\endcsname}}}.
     \notag
\end{align}
The coefficient of the last picture with label $k$ is
\begin{align*}
 c^3\sum_{g,h}a(g)a(h)\chi(g,h)^{-1}\chi(h,k)^{-1}
 &=c^3\sum_{g,h}a(g+h)\chi(h,k)^{-1}\\
 &=nc^3S_a\,\delta_{k,0}.
\end{align*}
Since a full cyclic rotation is the identity, this proves the first
identity in \eqref{eq:rotation-gauss}.  Finally, character orthogonality
gives
\[
 |S_a|^2=\sum_{t,h}a(h+t)\overline{a(h)}
        =\sum_t a(t)\sum_h\chi(t,h)^{-1}=n,
\]
and the asserted modulus of $c$ follows.

\label{lem: ghk}
If $g+h+k\ne0$, then
\begin{equation}\label{eq:triangle-charge}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D063\endcsname}}}=0.
\end{equation}

Insert a loop labelled by $l\in G$.  Its dimension is $1$; sliding it
through the three vertices gives
\begin{align}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D063\endcsname}}}
 &=\ensuremath{\vcenter{\hbox{\csname ngdiagram@D064\endcsname}}}
  =\ensuremath{\vcenter{\hbox{\csname ngdiagram@D065\endcsname}}},\notag\\
 &=\chi(l,g)\chi(l,h)\chi(l,k)\ensuremath{\vcenter{\hbox{\csname ngdiagram@D063\endcsname}}}.
 \label{eq:charge-loop-slide}
\end{align}
Hence $(1-\chi(l,g+h+k))$ times the original diagram is zero for every
$l$.  Since $\chi$ is nondegenerate and $g+h+k\ne0$, there exists an
$l$ for which this factor is nonzero.  This proves the claim.

\label{pro: real parameter}
There is a function $\beta:G\to\mathbb C$ such that
\begin{equation}\label{equ: real parameter}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D066\endcsname}}}
 =\beta(g)\sum_{h\in G}\chi(h,g)^{-1}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D067\endcsname}}}
   +\frac{\delta_{g,0}}{d_\varrho^2}\sum_{h\in G}\ensuremath{\vcenter{\hbox{\csname ngdiagram@D068\endcsname}}}.
\end{equation}

\label{thm: F-symbols}
In the preceding normalized gauge, the tetrahedral evaluations are
determined by $d_\varrho,\chi,a,c,\beta$, with the corner-transport map
\eqref{eq:vertex-rotation}.  The following are representatives;
the vertex corners and primed dual labels are as drawn.

For three or more invertible edges, the representatives are
\begin{equation}\label{eq:table-three-invertibles}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D010\endcsname}}}=1,\qquad \ensuremath{\vcenter{\hbox{\csname ngdiagram@D011\endcsname}}}=d_\varrho.
\end{equation}
For two invertible edges,
\begin{equation}\label{eq:table-two-invertibles}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D017\endcsname}}}=\chi(g,h)d_\varrho.
\end{equation}
For one invertible edge,
\begin{equation}\label{eq:table-one-invertible}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D079\endcsname}}}=\chi(g,h)\delta_{h,k}.
\end{equation}
For no invertible edge, abbreviate $p=h-g$ and $r=k-g$ in the
vertex labels:
\begin{equation}\label{eq:table-no-invertible}
 \ensuremath{\vcenter{\hbox{\csname ngdiagram@D080\endcsname}}}
 =\frac{a(h-g)a(k-g)}{a(h)a(k)}\,
    \chi(h,k)^{-1}\frac{\beta(k)}{d_\varrho}.
\end{equation}

\label{prop:beta-vertex-compatibility}
The scalar function $\beta$ satisfies
\begin{align}
 c a(g)\sum_{h\in G}\chi(g,h)^{-1}\beta(h)&=\beta(g),
       \label{eq:beta-rotation} \\
  \overline{\beta(g)}&=\frac{\beta(-g)}{a(g)}.
  \label{eq:beta-reality}
\end{align}

\label{thm:bulk-equations}
{For algebraic scalar data as in Definition~\ref{thm: equation},
the tetrahedra of Theorem~\ref{thm: F-symbols}, with
the bilinear transports of Lemma~\ref{lem:algebraic-tetra-transport},
satisfies every bulk TPE.}

\label{lem:algebraic-channel-inverse}
Let $G_V$ and $G_H$ be the trace Gram matrices of $(P_x;E_{hk})$ and
$(W_g;H_{pq})$, respectively. The channel matrix is invertible over $K$,
with
\begin{equation}\label{eq:algebraic-channel-inverse}
 T^{\mathsf T}G_VT=G_H,\qquad
 T^{-1}=G_H^{-1}T^{\mathsf T}G_V.
\end{equation}
In particular $T_{P_0,W_0}=(T^{-1})_{W_0,P_0}=d^{-1}$.

\label{cor:coarse-defect-bound}
Under the assumptions of Theorem~\ref{thm:unitarity-gap}, either
$\mathfrak d(\beta)=0$ or
\[
 \mathfrak d(\beta)>
 \frac{\kappa+\kappa^{-1}-2}{n}>\frac1{2n}.
\]
Consequently the single bound
\begin{equation}\label{eq:coarse-defect-bound}
 \sum_{g\in G}|\beta(g)|^2\le1-\frac1d+\frac1{2n}
\end{equation}
forces Hermitian reflection and unitary reconstruction. Equivalently,
one may check $\|U\|_{\mathrm F}^2\le n+n^2+n/2$.

\label{prop:unitary-galois-criterion}
\label{cor:unit-circle-reformulation}
\label{cor:coarse-galois-unitarity}
Let $\iota:L_n\hookrightarrow\mathbb C$ satisfy
$\iota(d_-)=d_+$. The transported tuple satisfies the unitary scalar
condition of Corollary~\ref{thm: reconstruction} precisely when
\begin{equation}\label{eq:unitary-galois-criterion}
 \overline{\iota(\beta(g))}
 =\frac{\iota(\beta(-g))}{\iota(a(g))}\qquad(g\in C_n),
\end{equation}
or, equivalently, when
\begin{equation}\label{eq:unit-circle}
 |\iota(F(k))|=1\qquad(1\leq k<n).
\end{equation}
Either of the following weaker bounds already implies these conditions:
\[
 |\iota(F(k))|\leq\sqrt2\quad(1\leq k<n),
 \qquad\text{or}\qquad
 \sum_{k=1}^{n-1}|\iota(F(k))|^2\leq n-\frac12.
\]
In each case the specifically reconstructed positive-root category
admits a unitary structure.

\label{prop:small-rank-unitarity}
The unit-circle conclusion of Conjecture~\ref{conj:unitary-galois}
holds for $1\leq n\leq6$. Consequently the positive-root categories
admit unitary structures for these orders.
